@GameTestHolder("wuxingxiantu_entry") @PrefixGameTestTemplate(false)
public final class AlchemyMigrationGameTests {
    static void eatImported(GameTestHelper h,GameTestPlayer p,ItemStack original,Runnable after){p.join();p.cleanupAfter(h,()->{});p.setNoGravity(true);p.keepTicking(h.getLevel(),p.blockPosition());p.getFoodData().setFoodLevel(10);p.getFoodData().setSaturation(0);p.getInventory().selected=0;p.getInventory().setItem(0,original);LegacyPillImport.ensure(p,0);h.runAfterDelay(25,()->{var stack=p.getMainHandItem();h.assertTrue(stack.getItem().use(h.getLevel(),p,InteractionHand.MAIN_HAND).getResult().consumesAction(),"Imported eating was not accepted");h.runAfterDelay(18,after);});}

    @GameTest(template="empty",timeoutTicks=200) public static void everyOldPillQualityRankAndRootElementHasDeterministicNineGradePlan(GameTestHelper h){int tested=0;for(var pill:PillCatalog.values())for(var quality:PillData.Grade.values())for(int rank=1;rank<=5;rank++)for(var element:pill==PillCatalog.ROOT?PillData.Element.values():new PillData.Element[]{PillData.Element.METAL})for(int cultivation=0;cultivation<(pill==PillCatalog.CULTIVATION?9:1);cultivation++){var old=MedicineTier.set(PillData.create(pill,quality,element,cultivation),rank);old.setCount(64);old.getOrCreateTag().putString("ThirdParty","preserved");var before=old.save(new CompoundTag());var a=LegacyPillImport.plan(old);var b=LegacyPillImport.plan(old);var result=PillSnapshot.read(a.result());h.assertTrue(result.grade()>=1&&result.grade()<=9&&result.quantity()==64&&a.result().equals(b.result())&&old.save(new CompoundTag()).equals(before)&&result.effects().size()<=9,"Invalid or mutating legacy conversion: "+pill+quality+rank+element);h.assertTrue(a.result().getString("SourceVersion").equals(LegacyPillImport.AUTHORITY),"Migration claimed a real reaction");tested++;}h.assertTrue(tested==680,"Catalog coverage shrank");var creation=LegacyPillImport.plan(new ItemStack(WuXingItems.CREATION_PILL.get()));h.assertTrue(PillSnapshot.read(creation.result()).effects().get(0).id()==Kind.creation_blessing,"Administrative creation item lost explicit service");h.succeed();}
    @GameTest(template="empty") public static void importWritesOriginalBackupAndRemovesActiveOldRankFieldsExactlyOnce(GameTestHelper h){try(var p=new GameTestPlayer(h.getLevel())){var old=MedicineTier.set(PillData.create(PillCatalog.ROOT,PillData.Grade.PERFECT,PillData.Element.WATER,0),5);old.setCount(7);old.getOrCreateTag().putString("ThirdParty","keep");var original=old.save(new CompoundTag());p.getInventory().setItem(0,old);h.assertTrue(LegacyPillImport.ensure(p,0),"Import failed");var result=p.getInventory().getItem(0);UUID id=result.getTag().getUUID(V5Batch.KEY);var journal=new BatchJournal(p.server);var authority=journal.imported(id);h.assertTrue(result.is(WuXingItems.V5_PILL.get())&&result.getCount()==7&&!result.getTag().contains("Grade")&&!result.getTag().contains(MedicineTier.KEY)&&!result.getTag().contains("Element")&&result.getTag().getString("ThirdParty").equals("keep"),"Old fields still settle or unrelated NBT lost");h.assertTrue(authority.getCompound("Original").equals(original)&&journal.importIntent(p.getUUID(),0).isEmpty(),"Exact backup or intent closure lost");LegacyPillImport.ensure(p,0);h.assertTrue(p.getInventory().getItem(0).getTag().getUUID(V5Batch.KEY).equals(id)&&journal.imported(id).equals(authority),"Reading imported pill rerolled or reissued authority");boolean rejected=false;try{ResearchEvidence.read(p,authority,Set.of());}catch(RuntimeException expected){rejected=true;}h.assertTrue(rejected&&AlchemyCertification.certifiedRank(p)==0,"Import minted reaction/certification evidence");}h.succeed();}
    @GameTest(template="empty") public static void constructorAliasArchiveAndPendingIntentRecoverAcrossSerialization(GameTestHelper h){try(var p=new GameTestPlayer(h.getLevel())){var raw=new CompoundTag();raw.putString("id","wuxingxiantu:root_water_perfect");raw.putByte("Count",(byte)3);var extra=new CompoundTag();extra.putString("Unknown","keep");raw.put("ForgeCaps",extra);var stack=ItemStack.of(raw);h.assertTrue(stack.getTag().getCompound("V5LegacyOriginal").equals(raw),"Pre-registry raw backup missing");var original=stack.save(new CompoundTag());var intent=new CompoundTag();UUID id=UUID.randomUUID();intent.putUUID("Id",id);intent.putString("SourceHash",LegacyPillImport.fingerprint(original));intent.put("Original",original);String policy;try(var stream=AlchemyMigrationGameTests.class.getResourceAsStream("/data/wuxingxiantu/alchemy/legacy-import.json")){policy=new String(stream.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);}catch(Exception error){throw new RuntimeException(error);}intent.putString("Policy",policy);var journal=new BatchJournal(p.server);journal.importIntent(p.getUUID(),0,intent);p.getInventory().setItem(0,ItemStack.of(original));LegacyPillImport.ensure(p,0);h.assertTrue(p.getMainHandItem().getTag().getUUID(V5Batch.KEY).equals(id)&&journal.imported(id).getCompound("Original").equals(original),"Interrupted import minted a new identity or lost backup");journal.importIntent(p.getUUID(),0,intent);LegacyPillImport.ensure(p,0);h.assertTrue(journal.importIntent(p.getUUID(),0).isEmpty(),"Saved-but-unacknowledged import not closed");}h.succeed();}
    @GameTest(template="empty",timeoutTicks=120) public static void importedPillUsesRealEatingAndCommonDoseAuthorityOnce(GameTestHelper h){var p=new GameTestPlayer(h.getLevel());p.join();p.cleanupAfter(h,()->{});p.setNoGravity(true);p.setPos(h.absolutePos(net.minecraft.core.BlockPos.ZERO).getX()+.5,210,h.absolutePos(net.minecraft.core.BlockPos.ZERO).getZ()+.5);p.keepTicking(h.getLevel(),p.blockPosition());var old=PillData.create(PillCatalog.GOLDEN_WOUND,PillData.Grade.LOW,PillData.Element.METAL,0);p.getInventory().setItem(0,old);LegacyPillImport.ensure(p,0);var imported=p.getMainHandItem().copy();UUID id=imported.getTag().getUUID(V5Batch.KEY);float gain=PillSnapshot.view(imported).effects().get(0).magnitudeMilli()/1000F;p.getFoodData().setFoodLevel(10);p.getFoodData().setSaturation(0);h.runAfterDelay(25,()->{p.setHealth(5);h.assertTrue(imported.getItem().use(h.getLevel(),p,InteractionHand.MAIN_HAND).getResult().consumesAction(),"Imported eating rejected");h.runAfterDelay(18,()->{h.assertTrue(p.getMainHandItem().isEmpty()&&Math.abs(p.getHealth()-(5+gain))<.01&&new BatchJournal(p.server).imported(id).getInt("DosesUsed")==1,"Imported dose was not frozen/paid once");p.setItemInHand(InteractionHand.MAIN_HAND,imported);h.assertTrue(!PillRuntime.canUse(p,imported),"Copied depleted legacy import still usable");h.succeed();});});}
    @GameTest(template="empty") public static void malformedOldFieldsAndUnknownNewMaterialsFailWithoutMutation(GameTestHelper h){var old=PillData.create(PillCatalog.AURA,PillData.Grade.LOW,PillData.Element.METAL,0);old.getOrCreateTag().putInt(MedicineTier.KEY,99);var before=old.copy();boolean rejected=false;try{LegacyPillImport.plan(old);}catch(RuntimeException expected){rejected=true;}h.assertTrue(rejected&&ItemStack.matches(old,before),"Corrupt old tier was silently revalued");rejected=false;try{AlchemyInputs.batchWithInert(List.of(new ItemStack(Items.DIAMOND_BLOCK)),InputDefinitions.current());}catch(RuntimeException expected){rejected=true;}h.assertTrue(rejected,"Unknown material quietly got generic V5 mass");h.succeed();}
    @GameTest(template="empty") public static void paidStoneAndFrostMetadataBecomeFrozenSpecsWithoutDoubleApplyingLegacy(GameTestHelper h){var old=PillData.create(PillCatalog.AURA,PillData.Grade.LOW,PillData.Element.METAL,0);var stone=old.getOrCreateTagElement(cn.blockforge.generated.generatedmod.importedcreatures.BeastMaterialEffects.STONE);stone.putInt("Duration",600);stone.putInt("Amplifier",2);var herb=new ItemStack(net.minecraftforge.registries.ForgeRegistries.ITEMS.getValue(net.minecraft.resources.ResourceLocation.parse("wuxingxiantu:herb_hanbing")));cn.blockforge.generated.generatedmod.plants.HerbAge.setYears(herb,500);var plan=new cn.blockforge.generated.generatedmod.alchemy.auxiliary.AuxiliaryAlchemy.Plan(List.of(new cn.blockforge.generated.generatedmod.alchemy.auxiliary.AuxiliaryAlchemy.Input(cn.blockforge.generated.generatedmod.alchemy.auxiliary.AuxiliaryAlchemy.Role.EFFECT,herb)));old=cn.blockforge.generated.generatedmod.alchemy.auxiliary.AuxiliaryAlchemy.finish(old,plan);var result=PillSnapshot.read(LegacyPillImport.plan(old).result());h.assertTrue(result.effects().stream().filter(s->s.id()==Kind.resistance).count()==1&&result.effects().stream().anyMatch(s->s.id()==Kind.resistance&&s.magnitudeMilli()==3000&&s.duration()>=600)&&result.effects().stream().anyMatch(s->s.id()==Kind.frost_strike),"Paid metadata lost or duplicated resistance");h.succeed();}
    @GameTest(template="empty") public static void worldDoseReplayDoesNotExpandMeridiansTwice(GameTestHelper h){try(var p=new GameTestPlayer(h.getLevel())){var effect=new Spec(Kind.meridian_expansion,2000,0,20,1,60,0);UUID receipt=UUID.randomUUID();PillWorldEffects.begin(receipt);try{ExtendedPillEffects.apply(p,effect);int bonus=GeneratedMod.data(p).wuxingxiantu$getAuraBonus();int used=MedicineProgress.state(p).getInt("ExpansionRealm0");GeneratedMod.data(p).wuxingxiantu$setAuraBonus(0);ExtendedPillEffects.apply(p,effect);h.assertTrue(GeneratedMod.data(p).wuxingxiantu$getAuraBonus()==bonus&&MedicineProgress.state(p).getInt("ExpansionRealm0")==used,"Cross-file retry duplicated quota or failed player recovery");PillWorldEffects.flush(p,receipt);}finally{PillWorldEffects.end();}}h.succeed();}
    @GameTest(template="empty",timeoutTicks=400) public static void registeredCatalogAndReferenceBalanceMatrixAreComplete(GameTestHelper h){try(var p=new GameTestPlayer(h.getLevel())){p.setPos(h.absolutePos(net.minecraft.core.BlockPos.ZERO).getX()+.5,210,h.absolutePos(net.minecraft.core.BlockPos.ZERO).getZ()+.5);var path=AlchemyCoverage.write(p,true);try{var report=com.google.gson.JsonParser.parseString(java.nio.file.Files.readString(path)).getAsJsonObject();h.assertTrue(report.get("passed").getAsBoolean()&&report.get("recipeCount").getAsInt()==140&&report.get("pillCount").getAsInt()==22&&report.get("templateCount").getAsInt()==26&&report.getAsJsonArray("devices").size()==6&&report.getAsJsonArray("fires").size()==9,"Catalog gaps: "+report.get("errors"));for(var row:report.getAsJsonArray("referenceSimulations"))h.assertTrue(row.getAsJsonObject().get("massConserved").getAsBoolean(),"Reference batch lost mass");com.mojang.logging.LogUtils.getLogger().info("ALCHEMY12_CATALOG_REPORT {}",path.toAbsolutePath());}catch(java.io.IOException error){throw new RuntimeException(error);}}h.succeed();}
    @GameTest(template="empty",timeoutTicks=200) public static void actualPaidClarificationRouteCanReachNineByDiscardingRawPotential(GameTestHelper h){try(var f=V5BatchGameTests.setup(h)){var herb=new ItemStack(net.minecraft.core.registries.BuiltInRegistries.ITEM.get(net.minecraft.resources.ResourceLocation.parse("wuxingxiantu:herb_huichun")),4);cn.blockforge.generated.generatedmod.plants.HerbAge.setYears(herb,1500);f.furnace().setItem(0,herb);h.assertTrue(f.furnace().startV5Batch(f.player()),"Cannot start real pure-healing batch");var doc=f.furnace().v5ServerRecord();var journal=new BatchJournal(f.player().server);for(int step=0;step<64&&doc.getString("State").equals("ACTIVE");step++){if(doc.getInt("ProcessStep")==9){long now=h.getLevel().getGameTime();for(int i=0;i<3;i++)doc=BatchIncidents.control(doc,246,now+i*5);h.assertTrue(doc.getInt("HeatMode")==0,"Accepted heat controls did not stop heating");}doc.putLong("LastWorldTick",h.getLevel().getGameTime()-20);doc=V5Batch.advance(doc,h.getLevel(),f.pos());journal.write(doc);}var result=PillSnapshot.read(doc.getCompound("PillResult"));h.assertTrue(result.grade()==9&&result.quantity()>=1&&result.purity()>=950000&&V5Batch.core(doc).ledger().lostPotential()>1000,"Nine-grade route is unreachable or purified by free power: "+result);h.assertTrue(doc.getList("ResearchControls",Tag.TAG_COMPOUND).size()==3,"Physical control provenance missing");}h.succeed();}
    @GameTest(template="empty") public static void bloodPotencyIsAnExplicitFactorAndBagPreservesItsIndependentLots(GameTestHelper h){try(var f=V5BatchGameTests.setup(h)){var ordinary=cn.blockforge.generated.generatedmod.importedcreatures.BeastMaterials.create(true,false);var king=cn.blockforge.generated.generatedmod.importedcreatures.BeastMaterials.create(true,true);f.furnace().setItem(1,ordinary);var a=ResearchInferenceGameTests.terminal(f,100,4,true);f.furnace().setItem(1,king);var b=ResearchInferenceGameTests.terminal(f,100,4,true);var x=ResearchEvidence.read(f.player(),a,Set.of());var y=ResearchEvidence.read(f.player(),b,Set.of());h.assertTrue(ResearchEvidence.differences(x.plan(),y.plan()).equals(List.of("materialPotency/0")),"Blood potency hidden in an apparently identical route");var second=cn.blockforge.generated.generatedmod.importedcreatures.BeastMaterials.create(true,false);UUID firstLot=ordinary.getTag().getUUID(cn.blockforge.generated.generatedmod.importedcreatures.BeastMaterials.LOT),secondLot=second.getTag().getUUID(cn.blockforge.generated.generatedmod.importedcreatures.BeastMaterials.LOT);ordinary.setCount(3);second.setCount(5);var bag=new cn.blockforge.generated.generatedmod.storage.BagInventory();bag.insert(ordinary);bag.insert(second);bag=cn.blockforge.generated.generatedmod.storage.BagInventory.load(bag.save());h.assertTrue(bag.entries.size()==1&&bag.entries.get(0).total()==8,"Blood lot metadata split storage entries");var one=bag.entries.get(0).take(64);var two=bag.entries.get(0).take(64);h.assertTrue(one.getCount()==3&&two.getCount()==5&&one.getTag().getUUID(cn.blockforge.generated.generatedmod.importedcreatures.BeastMaterials.LOT).equals(firstLot)&&two.getTag().getUUID(cn.blockforge.generated.generatedmod.importedcreatures.BeastMaterials.LOT).equals(secondLot)&&!one.getTag().contains(cn.blockforge.generated.generatedmod.plants.HerbAge.KEY),"Blood withdrawal forged a lot or a herb age");}h.succeed();}
}
